recipe('air-fryer-toad-in-the-hole','Sausage Yorkshire pudding tray',M,4,200,10,30,[(400,'sausage','Eight small sausages'),(125,'flour'),(100,'egg','Beaten'),(240,'milk'),(5,'oil')],['Whisk flour, eggs and milk until smooth. Leave the batter for 15 minutes while preparing the tin and sausages.','Brush a shallow approved metal tin with oil. Air fry sausages at 200°C for 8 minutes, then turn.','Pour batter around sausages, leaving expansion room. Cook for 15–22 minutes until the pudding is risen, the underside set and every sausage centre reaches 71°C. If the top darkens too soon, reduce to 180°C.'], 'Sausages bake into a crisp-edged Yorkshire pudding, divided into four substantial wedges.',wait=15,allergens=['wheat','gluten','egg','milk','sulphites'],equipment=['Shallow air-fryer-safe metal baking tin'],nutritionNote='Beef sausages replace pork sausages using a raw AFCD reference. Gravy and beans omitted. Batch fits only a large basket; use two batches if needed.')
recipe('big-mac-tacos-in-air-fryer','Cheeseburger tortilla pockets',Q,2,180,15,15,[(250,'beef'),(80,'tortilla','Two 40 g wraps'),(40,'cheddar','Sliced'),(10,'creamcheese'),(30,'onion','Finely diced'),(5,'mustard'),(40,'lettuce','Shredded'),(100,'freshTomato','Sliced'),(30,'pickle','Sliced'),(20,'mayo'),(40,'yoghurt'),(10,'ketchup')],['Mix beef, cream cheese, onion and mustard. Form two thin patties no thicker than 1.5 cm.','Air fry patties at 180°C for 10–12 minutes, turning halfway, until centres reach 71°C. Mix mayonnaise, yoghurt and tomato sauce.','Place each cooked patty on a tortilla and add cheddar. Air fry for 2–3 minutes to melt the cheese, then add salad, pickles and the sauce. Fold to eat.'],'Thin beef patties and melting cheddar sit in warm tortillas with crunchy salad and tangy burger sauce.',internal=71,allergens=['milk','egg','wheat','gluten'])
recipe('air-fryer-duck-breast','Crisp duck breast with ginger soy glaze',C,2,180,10,24,[[400,'duck meat with skin','F003634','Two boneless breasts; generic raw duck meat-and-skin reference'],(15,'soy'),(15,'honey'),(5,'ginger','Grated'),(5,'garlic','Grated')],['Pat duck dry and score only the skin in shallow parallel lines. Mix soy, honey, ginger and garlic; reserve half in a clean bowl.','Place duck skin-side down. Air fry at 180°C for 8 minutes, turn skin-side up and brush with the other half of the glaze. Continue for 10–16 minutes until 74°C in the thickest meat.','Rest for 5 minutes and slice across the grain. Finish with the clean reserved glaze.'],'Scored duck skin crisps above rich breast meat, finished with a small ginger, honey and soy glaze.',wait=5,internal=74,allergens=['soy','wheat','gluten'],nutritionNote='Uses generic raw duck meat and skin because AFCD breast reference is skinless. All skin and glaze counted; rendered fat is not deducted. Cook time increased to achieve poultry safety target.')
recipe('air-fryer-chilli-con-carne','Beef and kidney bean chilli',M,4,180,15,25,[(500,'beef'),(100,'onion','Finely diced'),(100,'carrot','Finely diced'),(400,'tomato'),(240,'beans','','canned'),(30,'paste'),(5,'cumin'),(3,'paprika'),(1,'chilli'),(2,'oregano')],['Spread mince, onion and carrot in a shallow approved dish. Air fry at 180°C for 9 minutes, breaking up the mince and stirring after 5 minutes.','Stir in tomatoes, beans, tomato paste and spices. Keep the mixture no deeper than 4 cm; divide between dishes if necessary.','Air fry for 12–16 minutes, stirring every 5 minutes, until bubbling and the mince reaches 71°C throughout.'],'Tomatoes and kidney beans turn air-fried beef mince into a spoonable chilli with cumin and smoked paprika.',allergens=[],equipment=['Shallow air-fryer-safe casserole dish'],nutritionNote='Commercial jar of chilli sauce replaced by measured tomato paste and spices. Rice and toppings excluded.')
recipe('air-fryer-pasta-bake','Beef and tomato pasta gratin',Q,4,180,15,25,[(400,'beef'),(200,'pasta','Weigh dry, then boil and drain','dried'),(400,'tomato'),(80,'onion','Finely diced'),(10,'garlic','Grated'),(30,'paste'),(100,'cheddar','Grated'),(2,'oregano')],['Boil pasta according to the packet and drain. Put beef, onion and garlic in a shallow approved dish and air fry at 180°C for 10 minutes, stirring twice, until mince reaches 71°C.','Mix cooked pasta with beef, tomatoes, paste and oregano. Divide into two shallow dishes if needed and scatter cheddar over the top.','Air fry at 180°C for 12–15 minutes until bubbling and 75°C in the middle. Allow 3 minutes before serving.'],'A measured beef and tomato sauce coats pasta beneath a browned cheddar crust.',wait=3,allergens=['wheat','gluten','milk'],equipment=['Saucepan','Shallow air-fryer-safe casserole dish'],nutritionNote='Defines dry pasta and homemade sauce amounts missing from the source. Dry pasta nutrient reference includes its absorbed cooking water at zero energy.')
recipe('air-fryer-sausage-bean-and-cheese-melt','Sausage and baked bean pastry parcels',Q,4,180,20,28,[(300,'short','Thawed'),(160,'sausage','Slice into 1 cm rounds'),(200,'bakedbeans','','canned'),(60,'cheddar','Grated'),(25,'egg','Beaten')],['Air fry sliced sausages at 180°C for 10 minutes, turning once, until 71°C. Cool briefly and combine with beans and cheese.','Cut pastry into four equal rectangles. Put filling on one half of each, leaving a border. Brush edges with egg, fold and crimp firmly.','Brush tops with remaining egg and cut steam slits. Air fry at 180°C for 15–18 minutes until pastry is cooked underneath and filling is 75°C.'],'Baked beans, sausage and cheddar make a hearty filling for four crisp shortcrust parcels.',allergens=['wheat','gluten','milk','egg','sulphites'],nutritionNote='Uses explicit commercial shortcrust and beef sausage weights. All pastry and filling counted; source homemade dough replaced.')
recipe('air-fryer-doner-kebab','Lamb doner pita with garlic yoghurt',M,4,160,20,45,[(600,'lamb'),(5,'cumin'),(3,'paprika'),(2,'oregano'),(10,'garlic','Grated; half for sauce'),(240,'pita','Four 60 g breads'),(160,'yoghurt'),(150,'cucumber','Sliced'),(150,'freshTomato','Sliced'),(100,'cabbage','Finely shredded'),(50,'onion','Thinly sliced')],['Knead lamb with spices and half the garlic for 2 minutes until sticky. Shape a compact loaf no thicker than 5 cm and wrap in foil only if permitted by the appliance manual.','Air fry at 160°C for 25 minutes. Open foil carefully to expose the top and cook at 180°C for 15–20 minutes until the centre reaches 71°C. Rest for 15 minutes, then slice thinly.','Mix yoghurt and remaining garlic. Fill pita breads with lamb slices and vegetables, then spoon over the yoghurt sauce.'],'Thin slices of spiced lamb loaf fill pita breads with shredded cabbage and cooling garlic yoghurt.',wait=15,allergens=['wheat','gluten','milk'],equipment=['Secure foil wrap approved for the appliance'],nutritionNote='Four defined portions replace large unspecified bread and sauce volumes. Foil must leave air circulation and stay away from the element.')
recipe('air-fryer-lasagna','Small-batch beef lasagne',M,4,180,20,35,[(400,'beef'),(100,'onion','Finely diced'),(400,'tomato'),(30,'paste'),(10,'garlic','Grated'),(180,'lasagne','Fresh sheets; cut to fit'),(150,'creamcheese'),(100,'milk'),(40,'cheddar','Grated'),(2,'oregano')],['Air fry beef, onion and garlic in a shallow approved dish at 180°C for 10 minutes, stirring twice, until mince reaches 71°C. Stir in tomatoes, paste and oregano.','Mix cream cheese with milk until spreadable. Layer beef sauce and fresh lasagne sheets in a shallow 18 cm dish, finishing with the cheese mixture and cheddar. Keep total depth below 5 cm.','Secure a permitted foil lid and air fry at 180°C for 15 minutes. Uncover and cook 8–10 minutes more until the sheets are tender and the centre reaches 75°C. Rest 5 minutes.'],'Fresh pasta sheets soften between beef sauce and a creamy cheese topping in a compact lasagne.',wait=5,internal=75,allergens=['wheat','gluten','egg','milk'],equipment=['18 cm shallow air-fryer-safe dish','Secure foil lid permitted by appliance manual'],nutritionNote='Fresh egg lasagne replaces pre-soaked dry sheets; measured cream cheese sauce replaces undefined Thermomix sauce. Recipe serves four, not the source oversized two portions.')
recipe('air-fryer-harvest-casserole','Sausage, apple and Brussels sprout roast',M,4,180,15,28,[(320,'sausage','Cut into 2 cm pieces'),(80,'bacon','Diced'),(300,'sweetpotato','Cut into 1.5 cm cubes'),(250,'apple','Cut into wedges'),(200,'sprouts','Quartered'),(100,'onion','Cut into wedges'),(10,'oil'),(2,'thyme')],['Toss sweet potato, apple, sprouts and onion with oil and thyme. Air fry at 180°C for 10 minutes, shaking halfway.','Add sausage and bacon pieces, spread everything into an even layer and cook for 12–15 minutes, turning twice.','Check sausage centres reach 71°C and sweet potato is tender. If needed, finish at 200°C for 3 minutes to brown the edges.'],'Sweet apple and roasted sprouts balance savoury sausage and bacon in a complete tray-style meal.',allergens=['wheat','gluten','sulphites'],nutritionNote='Beef sausages replace pork sausages; all produce is weighed rather than counted. A single layer may require two sequential batches, increasing time.')
